                <div className="p-3 rounded-xl bg-rose-50 border border-rose-200 flex items-start gap-2.5 text-xs text-rose-800 font-medium">
                  <span className="material-symbols-outlined text-[18px] text-rose-600 shrink-0">
                    error
                  </span>
                  <span>{recoveryError}</span>
                </div>
              )}

              <form onSubmit={handleResetPassword} className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                    Nueva contraseña
                  </label>
                  <div className="relative">
                    <input
                      type={showNewPassword ? 'text' : 'password'}
                      required
                      value={newPassword}
                      onChange={(e) => setNewPassword(e.target.value)}
                      placeholder="Mínimo 8 caracteres"
                      className="w-full h-11 pl-3.5 pr-10 rounded-xl bg-white border border-slate-300 text-sm text-slate-900 focus:outline-none focus:border-[#F2C94C] focus:ring-2 focus:ring-[#F2C94C]/30"
                    />
                    <button
                      type="button"
                      onClick={() => setShowNewPassword(!showNewPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 cursor-pointer"
                    >
                      <span className="material-symbols-outlined text-[19px]">
                        {showNewPassword ? 'visibility_off' : 'visibility'}
                      </span>
                    </button>
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1.5">
                    Confirmar nueva contraseña
                  </label>
                  <input
                    type={showNewPassword ? 'text' : 'password'}
                    required
                    value={confirmNewPassword}
                    onChange={(e) => setConfirmNewPassword(e.target.value)}
                    placeholder="Repite la nueva contraseña"
                    className="w-full h-11 px-3.5 rounded-xl bg-white border border-slate-300 text-sm text-slate-900 focus:outline-none focus:border-[#F2C94C] focus:ring-2 focus:ring-[#F2C94C]/30"
                  />
                </div>

                {/* Checklist de requisitos de seguridad */}
                <div className="p-3.5 rounded-xl bg-slate-50 border border-slate-200 space-y-1.5 text-xs">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block mb-1">
                    Requisitos de seguridad:
                  </span>
                  <div
                    className={`flex items-center gap-2 ${
                      hasMinLength ? 'text-emerald-700 font-semibold' : 'text-slate-500'
                    }`}
                  >
                    <span className="material-symbols-outlined text-[15px]">
                      {hasMinLength ? 'check_circle' : 'radio_button_unchecked'}
                    </span>
                    <span>Al menos 8 caracteres</span>
                  </div>
                  <div
                    className={`flex items-center gap-2 ${
                      hasUpperCase ? 'text-emerald-700 font-semibold' : 'text-slate-500'
                    }`}
                  >
                    <span className="material-symbols-outlined text-[15px]">
                      {hasUpperCase ? 'check_circle' : 'radio_button_unchecked'}
                    </span>
                    <span>Al menos una letra mayúscula (A-Z)</span>
                  </div>
                  <div
                    className={`flex items-center gap-2 ${
                      hasNumber ? 'text-emerald-700 font-semibold' : 'text-slate-500'
                    }`}
                  >
                    <span className="material-symbols-outlined text-[15px]">
                      {hasNumber ? 'check_circle' : 'radio_button_unchecked'}
                    </span>
                    <span>Al menos un número (0-9)</span>
                  </div>
                  <div
                    className={`flex items-center gap-2 ${
                      passwordsMatch
                        ? 'text-emerald-700 font-semibold'
                        : 'text-slate-500'
                    }`}
                  >
                    <span className="material-symbols-outlined text-[15px]">
                      {passwordsMatch
                        ? 'check_circle'
                        : 'radio_button_unchecked'}
                    </span>
                    <span>Ambas contraseñas coinciden</span>
                  </div>
                </div>

                <div className="flex flex-col-reverse sm:flex-row justify-end gap-2.5 sm:gap-3 pt-2 w-full">
                  <button
                    type="button"
                    onClick={() => setStep('forgot-code')}
                    className="w-full sm:w-auto px-4 py-2.5 rounded-xl border border-slate-300 text-slate-700 text-xs font-semibold hover:bg-slate-50 transition-colors cursor-pointer"
                  >
                    Atrás
                  </button>
                  <button
                    type="submit"
                    disabled={isSubmitting}
                    className="w-full sm:flex-1 justify-center py-2.5 px-5 rounded-xl bg-[#F2C94C] hover:bg-[#E0B83B] text-[#241A00] text-xs font-bold shadow-xs flex items-center gap-1.5 transition-all cursor-pointer"
                  >
                    <span className="material-symbols-outlined text-[17px]">
                      check_circle
                    </span>
                    <span>Actualizar contraseña</span>
                  </button>
                </div>
              </form>
            </div>
          )}

          {/* =================================================================
           * PASO 5: CONFIRMACIÓN DE CONTRASEÑA RESTABLECIDA
           * =============================================================== */}
          {step === 'forgot-success' && (
            <div className="bg-white rounded-2xl border border-slate-200/90 shadow-lg p-6 sm:p-8 text-center space-y-5 animate-in fade-in duration-150">
              <div className="w-14 h-14 rounded-2xl bg-emerald-50 border border-emerald-200 flex items-center justify-center text-emerald-600 mx-auto">
                <span className="material-symbols-outlined text-[32px]">
                  verified
                </span>
              </div>

              <div className="space-y-1.5">
                <h2 className="text-2xl font-extrabold text-slate-900">
                  ¡Contraseña actualizada!
                </h2>
                <p className="text-xs sm:text-sm text-slate-500 leading-relaxed">
                  Tu contraseña para{' '}
                  <strong className="text-slate-900">{recoveryEmail}</strong> se
                  ha restablecido con éxito. Ya puedes iniciar sesión con tu
                  nueva clave.
                </p>
              </div>

              <button
                type="button"
                onClick={() => setStep('login')}
                className="w-full h-11 rounded-xl bg-[#F2C94C] hover:bg-[#E0B83B] text-[#241A00] font-bold text-sm shadow-sm flex items-center justify-center gap-2 transition-all cursor-pointer"
              >
                <span className="material-symbols-outlined text-[18px]">
                  login
                </span>
                <span>Volver a Iniciar sesión</span>
              </button>
            </div>
          )}
        </div>

        {/* Footer de ayuda */}
        <div className="text-center text-xs text-slate-400 pt-4">
          ¿Problemas para ingresar? Contacta a{' '}
          <span className="font-semibold text-slate-600">
            soporte@planery.pe
          </span>
        </div>
      </div>
    </div>
  );
}

