            </thead>
            <tbody className="divide-y divide-[#E5E7EB] text-xs">
              {filtered.map((item) => {
                const isMenuOpen = openMenuId === item.id;
                return (
                  <tr
                    key={item.id}
                    className="hover:bg-slate-50/70 transition-colors group"
                  >
                    <td className="py-4 px-5">
