                    <td className="py-4 px-4 tabular-nums">
                      {item.budget > 0 ? (
                        <>
                          <div className="font-semibold text-slate-900 text-sm">
                            S/{' '}
                            {item.budget.toLocaleString('es-PE', {
                              minimumFractionDigits: 2,
                            })}
                          </div>
                          <span className="text-[10px] text-slate-400">
                            {item.budgetNote}
