interface ReenviarInvitacionModalProps {
  user: PlatformUser | null;
  onClose: () => void;
}

export const ReenviarInvitacionModal: React.FC<
  ReenviarInvitacionModalProps
> = ({ user, onClose }) => {
  const { resendPlatformUserInvitation } = usePlanery();

  if (!user) return null;

  const handleConfirm = () => {
    resendPlatformUserInvitation(user.id);
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-xs animate-in fade-in duration-150"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
    >
      <div
        className="relative w-full max-w-lg sm:max-w-xl mx-4 sm:mx-auto bg-white rounded-2xl shadow-2xl border border-[#E9ECEF] overflow-hidden"
