  const [priority, setPriority] = useState<TaskPriority>('Media');
  const [relatedProvider, setRelatedProvider] = useState(
    'Catering Gourmet Del Sur'
  );
  const [budgetCategory, setBudgetCategory] = useState(
    'Catering & Coctelería'
  );

