                onClick={() => setInvoiceFilter('Rechazado')}
                className={`px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-colors flex items-center gap-1 cursor-pointer ${
                  invoiceFilter === 'Rechazado'
                    ? 'bg-rose-600 text-white'
