cat << 'EOF' > "src/components/ui/Modal.tsx"
'use client';

import React, { useEffect } from 'react';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  subtitle?: string;
  icon?: string;
  iconClassName?: string;
  maxWidthClass?: 'max-w-md' | 'max-w-lg' | 'max-w-xl' | 'max-w-2xl' | 'max-w-4xl';
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  title,
  subtitle,
  icon,
  iconClassName = 'bg-amber-50 text-[#745B00]',
  maxWidthClass = 'max-w-lg',
  children,
}) => {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-xs animate-in fade-in duration-150"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
    >
      <div
        className={`relative w-full max-w-lg sm:max-w-xl ${maxWidthClass !== 'max-w-lg' ? `sm:${maxWidthClass}` : ''} mx-4 sm:mx-auto bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col max-h-[90vh]`}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Modal Header */}
        <div className="px-6 py-4 border-b border-slate-200 flex items-start justify-between gap-4 bg-white shrink-0">
          <div className="flex items-center gap-3 min-w-0">
            {icon && (
              <div
                className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${iconClassName}`}
              >
                <span className="material-symbols-outlined text-[20px]">
                  {icon}
                </span>
              </div>
            )}
            <div className="min-w-0">
              <h3 className="text-base sm:text-lg font-bold text-slate-900 leading-snug">
                {title}
              </h3>
              {subtitle && (
                <p className="text-xs text-slate-500 mt-0.5">{subtitle}</p>
              )}
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Cerrar modal"
            className="text-slate-400 hover:text-slate-700 hover:bg-slate-100 rounded-lg p-1.5 transition-colors shrink-0 cursor-pointer"
          >
            <span className="material-symbols-outlined text-[20px]">close</span>
          </button>
        </div>

        {/* Modal Content */}
        <div className="p-6 overflow-y-auto w-full">{children}</div>
      </div>
    </div>
  );
};

EOF

cat << 'EOF' > "src/components/ui/StatusBadge.tsx"
import React from 'react';

export interface StatusBadgeProps {
  status: string;
  showDot?: boolean;
  size?: 'xs' | 'sm';
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({
  status,
  showDot = true,
  size = 'sm',
}) => {
  const normalized = status.toLowerCase();

  let badgeColors = 'bg-slate-100 text-slate-700 border-slate-200';
  let dotColors = 'bg-slate-500';

  if (
    normalized.includes('confirmado') ||
    normalized.includes('pagado') ||
    normalized.includes('activo') ||
    normalized.includes('activa') ||
    normalized.includes('dentro del presupuesto') ||
    normalized.includes('completada') ||
    normalized.includes('contrato')
  ) {
    badgeColors = 'bg-emerald-50 text-emerald-800 border-emerald-200';
    dotColors = 'bg-emerald-500';
  } else if (
    normalized.includes('en progreso') ||
    normalized.includes('planificación') ||
    normalized.includes('cerca del límite') ||
    normalized.includes('en evaluación') ||
    normalized.includes('pendiente') ||
    normalized.includes('media') ||
    normalized.includes('comprobante')
  ) {
    badgeColors = 'bg-amber-50 text-amber-900 border-amber-200';
    dotColors = 'bg-amber-500';
  } else if (
    normalized.includes('seleccionado') ||
    normalized.includes('programado') ||
    normalized.includes('prueba') ||
    normalized.includes('cotización')
  ) {
    badgeColors = 'bg-sky-50 text-sky-800 border-sky-200';
    dotColors = 'bg-sky-500';
  } else if (
    normalized.includes('cancelado') ||
    normalized.includes('sobre presupuesto') ||
    normalized.includes('atrasada') ||
    normalized.includes('alta') ||
    normalized.includes('vencida') ||
    normalized.includes('anulado')
  ) {
    badgeColors = 'bg-rose-50 text-rose-700 border-rose-200';
    dotColors = 'bg-rose-500';
  } else if (normalized.includes('técnico') || normalized.includes('plano')) {
    badgeColors = 'bg-purple-50 text-purple-700 border-purple-200';
    dotColors = 'bg-purple-500';
  }

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border font-semibold whitespace-nowrap ${
        size === 'xs' ? 'px-2 py-0.5 text-[11px]' : 'px-2.5 py-1 text-xs'
      } ${badgeColors}`}
    >
      {showDot && <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${dotColors}`} />}
      <span>{status}</span>
    </span>
  );
};

EOF

cat << 'EOF' > "src/components/ui/Toast.tsx"
'use client';

import React from 'react';
import { usePlanery } from '../../context/PlaneryContext';

export const Toast: React.FC = () => {
  const { toast, hideToast } = usePlanery();

  return (
    <div
      className={`fixed bottom-6 right-6 bg-slate-900 text-white text-xs px-4 py-3 rounded-xl shadow-2xl border border-slate-800 flex items-center gap-2.5 transition-all duration-300 z-50 ${
        toast.visible
          ? 'opacity-100 translate-y-0 pointer-events-auto'
          : 'opacity-0 translate-y-3 pointer-events-none'
      }`}
    >
      <span
        className={`material-symbols-outlined text-[18px] ${
          toast.type === 'warning'
            ? 'text-amber-400'
            : toast.type === 'error'
            ? 'text-rose-400'
            : 'text-emerald-400'
        }`}
      >
        {toast.type === 'warning'
          ? 'warning'
          : toast.type === 'error'
          ? 'error'
          : 'check_circle'}
      </span>
      <span className="font-medium">{toast.message}</span>
      <button
        type="button"
        onClick={hideToast}
        className="ml-2 text-slate-400 hover:text-white transition-colors"
      >
        <span className="material-symbols-outlined text-[16px]">close</span>
      </button>
    </div>
  );
};

